export const meta = {
  name: 'explore-5-points',
  description: 'Read-only exploration of the code behind 5 requested V1 changes',
  phases: [{ title: 'Explore' }],
}
const COMMON = `Repo root: C:\\travaille\\godot\\towermoulineux2 (Godot client in godot/, Go server in serveur/, C++ sim in lhtcpp/, docs in docs/). READ-ONLY: do not modify anything. Also check docs/v1/DECISIONS.md, docs/v1/CONTRACTS.md, docs/V1_scope_prompt.md and docs/LHT2_GDD_v0.3.md for rules relevant to your topic (grep them). Report concrete file paths with line numbers, the current behaviour, the relevant data flow, existing reusable functions, tests that cover it, and open design questions the product owner must answer. Be factual and concise (<= 900 words).`
const TOPICS = [
  { key: 'lang', p: `Topic: a LANGUAGE SELECTION MENU is wanted. Find how player-visible texts are produced today in the Godot client: hard-coded French strings, tr()/TranslationServer usage, .po/.csv translation files, project.godot internationalization settings, existing settings/options menu, main menu / profile screens, where a menu entry could live, how settings are persisted (user://, server profile?). Count roughly how many hard-coded player-visible strings exist and where (core vs scenes). Check scope §17 / any rule about language in V1 scope and DECISIONS.` },
  { key: 'wait', p: `Topic: the UI still shows a LEFTOVER of the "waiting while a building is being built/upgraded" system (timers, progress bars, countdowns, 'en construction', 'en cours', pending upgrade states) which is no longer wanted: recent commits 86be9a0 "feat(village): apply building upgrades at once" and c9ca01c "D-368" made upgrades immediate. Run git show --stat on those commits and inspect what remains: Godot UI nodes/scripts/texts, server fields (e.g. upgrade_ends_at, pending, construction queue), contracts, tests, translations. List every remnant precisely (file:line) and whether removing it is client-only or touches server/API.` },
  { key: 'towers', p: `Topic: GAMEPLAY rule wanted: "no limit on the number of towers as long as a path stays valid". Find every current limit on tower count/placement: in the C++ sim (lhtcpp/), Go server (serveur/) validation, game data (docs/LHT2_Stat_GDD - Tower.csv, data files under serveur or godot), Godot client placement UI (budgets, slots, caps, gold/cost), and the path-validity check (pathfinding blocking check) — where it lives and whether client and server both run it. Identify what "limit" likely refers to (max towers per layout? per building level? resource cost?) and what would need to change, including tests and data versioning (§38).` },
  { key: 'hp', p: `Topic: GAMEPLAY+UI: the titan's HEALTH PORTIONS must be shown more clearly. Find how the titan HP is modeled (sim: phases/segments/portions/thresholds? last hit rules — the game is 'Last Hit Titan'), how the Godot client displays it today (health bar scene/script, segments, numbers, colors), data from server (combat result timeline/events), and GDD rules about titan HP portions / last hit / shares between players. Describe the current visual and what data is available to draw segmented portions.` },
  { key: 'cam', p: `Topic: GAMEPLAY+UI: the camera must ALWAYS FOCUS the fight zone when a titan is present. Find the Godot camera system (camera controller script, zoom/pan, user input, follow logic), the combat playback/visualisation scene, how the titan position is known over time, when a titan 'is there' (combat start/end, waves, path), and any existing focus/follow code. Describe current behaviour and whether user camera control must be locked or merely recentered.` },
]
const res = await parallel(TOPICS.map(t => () => agent(`${t.p}\n\n${COMMON}`, { label: `explore:${t.key}`, phase: 'Explore', agentType: 'Explore' }).then(r => ({ key: t.key, report: r }))))
return res.filter(Boolean)

