Implementer report: ${impl.summary}\nOpen issues claimed: ${impl.open_issues.join(' | ')}
${ENV}
You may run tests in that worktree (LHT_TEST_HTTP_PORT=${c.rport}) but do NOT modify files. Report ONLY real defects with concrete evidence (file:line, CSV row). Empty list if nothing real.`, { label: `review:${c.key}`, phase: 'Review', schema: REVIEW_SCHEMA })
      .then(r => ({ impl, issues: (r?.issues || []).filter(x => x.severity !== 'low'), low: (r?.issues || []).filter(x => x.severity === 'low') }))
  },
  (rev, c) => {
    if (!rev) return null
    const all = [...rev.issues, ...rev.low]
    if (!all.length) return { ...rev, fix: null }
    return agent(`You continue i18n branch ${rev.impl.branch} in its existing worktree ${rev.impl.worktree_path} (cd there; no new worktree or branch). The reviewer reported:\n${JSON.stringify(all, null, 1)}\nFor each (including low ones that are cheap): verify; fix if real (translations too) or reject with a precise reason. Re-import, rerun the full run_tests (0 failed) and lint (0 WARNING), commit. Port LHT_TEST_HTTP_PORT=${c.port}.\n${RULES}\n${ENV}`, { label: `fix:${c.key}`, phase: 'Fix', schema: FIX_SCHEMA }).then(fix => ({ ...rev, fix }))
  })
return { wave3: results.filter(Boolean) }

