 else if(c=='"')q=true;else if(c==','){row.push(f);f='';}else if(c=='\n'){row.push(f);rows.push(row);row=[];f='';}else if(c!='\r')f+=c;}
 if(f||row.length){row.push(f);rows.push(row);}return rows;}
const by={};
for(const f of fs.readdirSync(dir).filter(f=>f.endsWith('.csv'))){const rows=parse(fs.readFileSync(dir+'/'+f,'utf8'));
 for(const r of rows.slice(1)){if(!r[0])continue;(by[r[0]]??=[]).push({t:f,v:r.slice(1).join('\u241f')});}}
