	return options


static func is_valid_profile_name(name: String) -> bool:
	if _profile_pattern == null:
		_profile_pattern = RegEx.create_from_string("^[a-z0-9_-]{2,24}$")
	return _profile_pattern.search(name) != null


func is_valid() -> bool:
	return errors.is_empty()


func auth_mode_name() -> String:
	return "steam" if auth_mode == AuthMode.STEAM else "dev"


func is_loopback_server() -> bool:
	return LOOPBACK_HOSTS.has(str(TcpProbe.endpoint_of(server_base_url)["host"]))


## "profil alice · http://127.0.0.1:8080 · auth dev"
func describe() -> String:
	return Tx.f("profil {profile} · {server} · auth {auth}", {"profile": profile_name, "server": server_base_url, "auth": auth_mode_name()})


## The errors in the active language.
func error_texts() -> Array[String]:
	var texts: Array[String] = []
	for entry: Dictionary in _error_entries:
		texts.append(Tx.f(str(entry["msgid"]), entry["args"] as Dictionary))
	return texts


func _add_error(msgid: String, args: Dictionary) -> void:
	errors.append(msgid.format(args))
	_error_entries.append({"msgid": msgid, "args": args})


func _parse_auth(value: String) -> void:
	match value:
		"dev":
			auth_mode = AuthMode.DEV
		"steam":
			auth_mode = AuthMode.STEAM
		_:
			_add_error(AUTH_ERROR, {"mode": value})


func _set_server_url(url: String) -> void:
	var normalized: String = url.strip_edges().trim_suffix("/")
	var endpoint: Dictionary = TcpProbe.endpoint_of(normalized)
	var host: String = endpoint["host"]
	var port: int = endpoint["port"]
	if host.is_empty() or port <= 0 or port > 65535:
		_add_error(SERVER_ERROR, {"url": url})
		return
	if host.to_lower() == "localhost":
		normalized = with_ipv4_loopback(normalized)
		warnings.append("« localhost » remplacé par %s (le serveur local n'écoute qu'en IPv4) : %s" % [LOCALHOST_IPV4, normalized])
	server_base_url = normalized
	if not is_loopback_server():
		warnings.append("Serveur non local : %s" % normalized)


## `url` with a "localhost" host (any case) replaced by 127.0.0.1.
static func with_ipv4_loopback(url: String) -> String:
	if _localhost_pattern == null:
		_localhost_pattern = RegEx.create_from_string("(?i)^(https?://)localhost(?=[:/?#]|$)")
	return _localhost_pattern.sub(url, "${1}" + LOCALHOST_IPV4)

