  decisions: { type: 'array', items: { type: 'string' } }, open_issues: { type: 'array', items: { type: 'string' } }, needs_user: { type: 'boolean' } },
  required: ['branch', 'worktree_path', 'commits', 'summary', 'tests', 'decisions', 'open_issues', 'needs_user'] }
