export const meta = {
  name: 'wave6-1',
  description: 'Wave 6.1: world HP x3, parchment filter fix, panel layouts/card grid, action bar per view, menu camp with wind, audio — implement, review, fix (6 branches)',
  phases: [{ title: 'Implement' }, { title: 'Review' }, { title: 'Fix' }],
}
const SP = 'C:\\Users\\akitl\\AppData\\Local\\Temp\\claude\\C--travaille-godot-towermoulineux2\\7020066a-783a-415a-a50d-d8623080aee1\\scratchpad\\'
const ENV = `
ENVIRONMENT OF THIS MACHINE (overrides the Godot path and Postgres port written in CLAUDE.md, which come from another machine):
- Main repo: C:\\travaille\\godot\\towermoulineux2, integration branch 'v1' (HEAD 1a48921 or later; 862 Godot tests pass, lint 0 WARNING, ART_CHECKS_OK; Go 33/33). Never push, never touch remotes, never ssh. Commits: Conventional Commits in English with scope, ending "Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>". Never edit docs/v1/* or CLAUDE.md (the orchestrator does; put needs in your report).
- Godot 4.7.2 ONLY: headless /c/travaille/godot/Godot_v4.7.2-stable_win64_console.exe ; windowed (captures): /c/travaille/godot/Godot_v4.7.2-stable_win64.exe. Fresh worktree: \`$G --headless --path godot --import\` TWICE. Re-import after CSV/asset edits. Tests: \`LHT_TEST_HTTP_PORT=<your port> $G --headless --path godot --script res://tests/run_tests.gd\` (0 failed). Lint: \`$G --headless -d --path godot --script res://tests/check_scripts.gd < /dev/null\` (0 WARNING). Art: \`$G --headless --path godot --script res://art/tests/art_checks.gd\` (ART_CHECKS_OK). Captures: \`$GW --path godot --script res://tools/capture/capture.gd -- --shots=res://tools/capture/shots/<list>.json --out=<dir> [--only=..] [--resolutions=..] [--lang=..]\` windowed; READ the PNGs with the Read tool. Keep PNGs out of git (under $TEMP).
- Go: \`export PATH=/c/mingw64/bin:$PATH\`; TD_SIM_CLI=C:/travaille/godot/towermoulineux2/lhtcpp/build-release/td_sim_cli.exe ; LHT_REQUIRE_ENGINE=1 ; Postgres of the project on 127.0.0.1:55432 (NOT 5432 — a foreign Postgres owns 5432, never touch it): LHT_TEST_DATABASE_URL='postgres://lht2:lht2_dev_password@127.0.0.1:55432/lht2_test?sslmode=disable'; set TMP to a dir you create under $TEMP. Never run docker compose. Port 8080 is foreign. Stop processes you start by PID only. Temp: $TEMP/lht-<branch>/.
- Context: approved plan C:\\Users\\akitl\\.claude\\plans\\nifty-rolling-crane.md ; designs ${SP}w6\\design_hud_world_audio.md, ${SP}w6\\design_menu_lht1.md, ${SP}w6\\design_ui.md ; rules CLAUDE.md, godot/README.md ; decisions docs/v1/DECISIONS.md (next free: D-401; propose new ones in your report, the orchestrator numbers them).
- I18N RULES: player-visible text = French msgid byte-identical through Tx.t/f/n (named {params}, CLDR plurals "|"), translations in godot/i18n/<chunk>.csv (all 8 columns en,es,de,ja,ko,zh,pt,ru filled, following ${SP}glossary.csv and ${SP}i18n_style.md; a msgid present in two tables must have identical translations; reuse an existing msgid when identical); code-set Labels use auto_translate_mode DISABLED and re-render on NOTIFICATION_TRANSLATION_CHANGED; test_no_hardcoded_french, test_translations_complete and the per-domain i18n tests must stay green; server texts never translated; tests pinned to fr; NEVER replay/rejeu or equivalent shown to the player in any language.
- Conventions: GDScript static typing, tabs, class_name after extends, fixed children of a scene declared in its .tscn (%Unique) — code only instantiates data-dependent nodes; logic in godot/core/; comments rare (why only); a test for every new logic.`

const BRANCHES = [
  { key: 'world-hp', port: 18080, rport: 18086, text: `Branch v1-w6-world-hp — World titans HP ×3 keeping the total gold of a titan (design section C). You own serveur/** ONLY. Change titans.json hp_per_player (16200/18000/21600) and world.json hp_per_gold 450; adapt internal/world/balance_test.go (4.5–9 visits per player, maxVisits 120, rename the test), revise C4 (internal/balance/criteria.go MinKillsPerHour) to the measured value with margin, and run the balance reports (LHT_BALANCE_REPORT=1 ... -run 'TestBalanceReport|TestWorldBalanceReport|TestProgressionReport' -v ./internal/...) — paste the key measured numbers (visits per titan, kills per hour, C1–C5 verdicts, gold per hour from the world) in your report. IF C1, C2 or C3 FAIL with the new values: do NOT retune anything else; keep the branch at the requested values, mark needs_user=true and explain with numbers and the two options (hp_per_gold 300 or keep 150). Fix other Go tests impacted (rewards.World assertions etc.). gofmt, go vet, full go test ./... with the env. Also check the client fixtures/fake server only if a Godot test depends on the real data files (it should not).` },
  { key: 'planning-filter', port: 18081, rport: 18087, text: `Branch v1-w6-planning-filter — parchment bug (design section B): with "Masquer les tours posées" checked, a placed tower stays in the list. You own godot/scenes/planning/planning_screen.gd and godot/tests/scenes/planning/test_planning_screen.gd only. Fix via Game.state.layout.changed → _refresh_list() when hide_placed (connect in open, disconnect in close), refresh the shown-count text, and add the regression test(s) (place → gone, remove → back, revert/Annuler → back).` },
  { key: 'ui-frame', port: 18082, rport: 18088, text: `Branch v1-w6-ui-frame — panel layouts for the coming village redesign (design_ui.md section (b), first two bullets). You own godot/scenes/ui/side_panel/**, godot/scenes/ui/card_grid/** (new), the show_side_panel part of godot/scenes/valley/valley.gd, godot/theme/lht_theme_builder.gd ONLY to add the new variation names (WindowFrame, WindowHeader, CardButton, SlotPanel, TabButton, PricePlate, TooltipPanel) as FLAT StyleBoxFlat placeholders matching today's look (the SVG frames come in wave 6.2) + the regenerated godot/theme/lht_theme.tres via the project's theme build tool (find it: tools/project/build_theme.gd or similar), and their tests (tests/scenes/ui/test_side_panel.gd, new test_card_grid.gd, tests/theme/test_theme.gd for the new variations). SidePanel: enum Layout {SIDE, GRID, WIDE}, area_for(screen,left,layout) + area(), header_actions(), WIDE close icon button still named CloseButton, WIDE uses Overlay.hold_while_visible in valley.show_side_panel. Today's panels keep SIDE and must look/behave exactly as before (all existing village/combat/world tests and test_village_panel_fit green). Do not touch village panels themselves.` },
  { key: 'action-bar', port: 18083, rport: 18089, text: `Branch v1-w6-action-bar — action bar per view (design section A). You own godot/core/presentation/bar_visibility.gd (new), godot/scenes/hud/hud.gd, the BUTTON-related parts of godot/scenes/combat/combat_module.gd, godot/scenes/village/village_module.gd and godot/scenes/world/world_module.gd, godot/i18n/village_ui.csv (append rows), the hud/village/combat/world/core-presentation tests, tests/e2e only if a bar button driver breaks, and godot/tools/capture/shots/{village,valley_review}.json (+ their capture stages if a village-view bar shot is needed). Defense view: Défense, Village | Parchemin, Quête principale, Chasses, Titan mondial | Menu (no QG). Village view: Défense, Village | 7 building buttons in catalog order, greyed (modulate) but clickable when not built/locked/decor | Menu. Single rule combinator BarVisibility (rules view/fight/world never overwrite each other). Windowed captures at 1920x1080 and 1280x720 of the bar in both views (and during a fight) — READ them; icons-only/compact modes must stay inside margins.` },
  { key: 'menu-camp', port: 18084, rport: 18090, text: `Branch v1-w6-menu-camp — main menu camp with wind and drifting clouds (design_menu_lht1.md section 1). You own godot/art/scenes/**, godot/art/shaders/{wind,cloud}.gdshader, godot/art/materials/{foliage,cloth}.tres, godot/art/meshkit/art_materials.gd, godot/art/fx/campfire.tscn, godot/addons/lht_models/** (roles), godot/legacy/procedural_art/** (generator; regenerate camp.glb and the changed backdrop/outcrop with the archived export tool as documented in godot/README.md), godot/assets/models/sky/**, godot/art/tests/check_backdrop.gd (+ check_meshkit if needed), godot/tools/capture/shots/menu.json, godot/tests/scenes/menu/menu_capture_stage.gd, and the "Modèles 3D" section of godot/README.md. art_checks must stay OK (engine warnings count as failures; model import rules pinned). Windowed captures of the whole menu list (menu.json) incl. new camp views and two shots taken ~2 s apart to show motion — READ them and iterate on composition until the camp reads well (trees, banner, fire, smoke visible bottom-right; descent still clear). Report the captures you read with a verdict.` },
  { key: 'audio', port: 18085, rport: 18091, text: `Branch v1-w6-audio — first audio integration (design section D). You own godot/core/audio/** (new), godot/core/autoload/audio.gd (new), godot/default_bus_layout.tres (new), godot/project.godot (autoload + bus layout only), godot/assets/audio/** (git mv renames without spaces, .import fixed), godot/core/session/{profile_settings,settings_applier}.gd, godot/scenes/ui/settings/**, the CSV of the domain that owns the settings panel texts, tests (tests/core/audio/**, tests/project/test_project_settings.gd, tests/scenes/menu/test_main_menu.gd, tests/core/session/**), README.md (third-party audio note). Mapping: calm music on menu & valley, boss music while a fight is presented (Game.state.presentation_hold_changed), click on every BaseButton press, error sound on WARNING/ERROR toasts (rate-limited), Music & Effects volume sliders in Paramètres (D-259 revised). Do NOT edit godot/scenes/planning/**. Headless tests check intent (current_track, last_sfx, bus volumes). Make sure the full test suite does not become noisy/slow and no engine warning appears (art_checks/lint).` },
]

const IMPL_SCHEMA = { type: 'object', properties: {
  branch: { type: 'string' }, worktree_path: { type: 'string' }, commits: { type: 'array', items: { type: 'string' } }, summary: { type: 'string' }, tests: { type: 'string' },
  decisions: { type: 'array', items: { type: 'string' } }, open_issues: { type: 'array', items: { type: 'string' } }, needs_user: { type: 'boolean' } },
  required: ['branch', 'worktree_path', 'commits', 'summary', 'tests', 'decisions', 'open_issues', 'needs_user'] }
const REVIEW_SCHEMA = { type: 'object', properties: { issues: { type: 'array', items: { type: 'object', properties: {
  severity: { type: 'string', enum: ['high', 'medium', 'low'] }, file: { type: 'string' }, description: { type: 'string' }, evidence: { type: 'string' } },
  required: ['severity', 'file', 'description', 'evidence'] } } }, required: ['issues'] }
const FIX_SCHEMA = { type: 'object', properties: { fixed: { type: 'array', items: { type: 'string' } }, rejected: { type: 'array', items: { type: 'string' } }, commits: { type: 'array', items: { type: 'string' } }, tests: { type: 'string' } }, required: ['fixed', 'rejected', 'commits', 'tests'] }

const results = await pipeline(
  BRANCHES,
  b => agent(`You implement ${b.text}
In your OWN worktree first run \`git switch -c v1-w6-${b.key} && git reset --hard v1\` (worktrees are created from master). Stay strictly inside the paths you own; if you need a change elsewhere, describe it in open_issues instead. Keep everything green: full run_tests 0 failed, lint 0 WARNING, art_checks OK (and the Go suite if you touch serveur/). Atomic commits. Your port: LHT_TEST_HTTP_PORT=${b.port} (server ports if needed: ${b.port}).
${ENV}
Report: branch, worktree path, commits, summary of what you did and how it is tested, test results (counts), decisions to record (one line each, French or English), open issues, needs_user (true only if a user decision is required).`, { label: `impl:${b.key}`, phase: 'Implement', isolation: 'worktree', schema: IMPL_SCHEMA }).then(r => ({ b, impl: r })),
  ({ b, impl }) => {
    if (!impl) return { b, impl: null, issues: [] }
    return agent(`ADVERSARIAL REVIEW of branch ${impl.branch} in worktree ${impl.worktree_path} (diff: \`git -C ${impl.worktree_path} diff v1...HEAD\`). Task it implemented: ${b.text}
Implementer summary: ${impl.summary}
Implementer open issues: ${impl.open_issues.join(' | ')}
Try to refute that it is correct and complete: wrong or missing behaviour vs the design and the user's decisions, regressions elsewhere (run the full Godot suite and, if serveur/ changed, the Go suite there with your port), missing tests, i18n rule violations, scene-composition rule violations, art/model rule violations, edits outside the owned paths, leftovers. For visual work, take your own windowed captures and READ them. Do NOT modify tracked files in that worktree (scratch copies under $TEMP/lht-review-${b.key}/). Report only real defects with concrete evidence; empty list if none. Your port: LHT_TEST_HTTP_PORT=${b.rport}.
${ENV}`, { label: `review:${b.key}`, phase: 'Review', schema: REVIEW_SCHEMA }).then(r => ({ b, impl, issues: r?.issues || [] }))
  },
  ({ b, impl, issues }) => {
    if (!impl || !issues.length) return { b, impl, issues, fix: null }
    return agent(`You continue branch ${impl.branch} in its existing worktree ${impl.worktree_path} (cd there; no new worktree or branch). The reviewer reported:
${JSON.stringify(issues, null, 1)}
For each issue: verify; fix if real (test for logic) or reject with a precise reason; product decisions → reject with reason for the orchestrator. Stay inside the paths the branch owns (${b.text.slice(0, 300)}...). Re-import if needed, rerun full run_tests (0 failed), lint (0 WARNING), art_checks, and the Go suite if serveur/ changed; re-capture and READ affected views if visuals changed. Commit. Port LHT_TEST_HTTP_PORT=${b.port}.
${ENV}`, { label: `fix:${b.key}`, phase: 'Fix', schema: FIX_SCHEMA }).then(f => ({ b, impl, issues, fix: f }))
  },
)
return results.filter(Boolean).map(r => ({ key: r.b.key, impl: r.impl, issues: r.issues, fix: r.fix }))

