const IMPL_SCHEMA = { type: 'object', properties: {
  branch: { type: 'string' }, worktree_path: { type: 'string' }, commits: { type: 'array', items: { type: 'string' } }, summary: { type: 'string' }, tests: { type: 'string' },
  decisions: { type: 'array', items: { type: 'string' } }, open_issues: { type: 'array', items: { type: 'string' } }, needs_user: { type: 'boolean' } },
  required: ['branch', 'worktree_path', 'commits', 'summary', 'tests', 'decisions', 'open_issues', 'needs_user'] }
const REVIEW_SCHEMA = { type: 'object', properties: { issues: { type: 'array', items: { type: 'object', properties: {
  severity: { type: 'string', enum: ['high', 'medium', 'low'] }, file: { type: 'string' }, description: { type: 'string' }, evidence: { type: 'string' } },
  required: ['severity', 'file', 'description', 'evidence'] } } }, required: ['issues'] }
const FIX_SCHEMA = { type: 'object', properties: { fixed: { type: 'array', items: { type: 'string' } }, rejected: { type: 'array', items: { type: 'string' } }, commits: { type: 'array', items: { type: 'string' } }, tests: { type: 'string' } }, required: ['fixed', 'rejected', 'commits', 'tests'] }

const results = await pipeline(
  BRANCHES,
  b => agent(`You implement ${b.text}
In your OWN worktree first run \`git switch -c v1-w6-${b.key} && git reset --hard v1\` (worktrees are created from master). Stay strictly inside the paths you own; if you need a change elsewhere, describe it in open_issues instead. Keep everything green: full run_tests 0 failed, lint 0 WARNING, art_checks OK. Atomic commits. Your port: LHT_TEST_HTTP_PORT=${b.port}.
${ENV}
Report: branch, worktree path, commits, summary of what you did and how it is tested, test results (counts), captures read (paths + verdict), decisions to record (one line each, French or English), open issues, needs_user (true only if a user decision is required).`, { label: `impl:${b.key}`, phase: 'Implement', isolation: 'worktree', schema: IMPL_SCHEMA }).then(r => ({ b, impl: r })),
  ({ b, impl }) => {
    if (!impl) return { b, impl: null, issues: [] }
    return agent(`ADVERSARIAL REVIEW of branch ${impl.branch} in worktree ${impl.worktree_path} (diff: \`git -C ${impl.worktree_path} diff v1...HEAD\`). Task it implemented: ${b.text}
Implementer summary: ${impl.summary}
Implementer open issues: ${impl.open_issues.join(' | ')}
Try to refute that it is correct and complete: wrong or missing behaviour vs the design and the user's words, regressions elsewhere (run the full Godot suite with your port), missing tests, i18n rule violations, scene-composition rule violations, art rule violations, edits outside the owned paths, leftovers, panels that overflow at 1280x720 / 125 % or in ru/de. Take your own windowed captures of the changed views and READ them — judge them as a player would: does it look like a crafted fantasy game UI rather than a web page? Do NOT modify tracked files in that worktree (scratch copies under $TEMP/lht-review-${b.key}/). Report only real defects with concrete evidence; empty list if none. Your port: LHT_TEST_HTTP_PORT=${b.rport}.
${ENV}`, { label: `review:${b.key}`, phase: 'Review', schema: REVIEW_SCHEMA }).then(r => ({ b, impl, issues: r?.issues || [] }))
  },
  ({ b, impl, issues }) => {
    if (!impl || !issues.length) return { b, impl, issues, fix: null }
    return agent(`You continue branch ${impl.branch} in its existing worktree ${impl.worktree_path} (cd there; no new worktree or branch). The reviewer reported:
${JSON.stringify(issues, null, 1)}
For each issue: verify; fix if real (test for logic) or reject with a precise reason; product decisions → reject with reason for the orchestrator. Stay inside the paths the branch owns (${b.text.slice(0, 400)}...). Re-import if needed, rerun full run_tests (0 failed), lint (0 WARNING), art_checks; re-capture and READ affected views if visuals changed. Commit. Port LHT_TEST_HTTP_PORT=${b.port}.
${ENV}`, { label: `fix:${b.key}`, phase: 'Fix', schema: FIX_SCHEMA }).then(f => ({ b, impl, issues, fix: f }))
  },
)
return results.filter(Boolean).map(r => ({ key: r.b.key, impl: r.impl, issues: r.issues, fix: r.fix }))

