// Wave 6.2 doc update (orchestrator). Usage: node doc62.js <repo> <tests> <scripts> <artchecks> <head>
const fs = require("fs");
const path = require("path");
const [repo, tests, scripts, art, head] = process.argv.slice(2);
const p = (f) => path.join(repo, "docs", "v1", f);
function edit(file, pairs) {
	let t = fs.readFileSync(p(file), "utf8");
	for (const [a, b] of pairs) {
		if (!t.includes(a)) throw new Error(file + ": missing " + a.slice(0, 80));
		t = t.replace(a, b);
	}
	fs.writeFileSync(p(file), t);
}
const D = "2026-10-16";
const decisions = `

### Retours de réunion du 2026-10-16 — vague 6.2

- D-416 · ${D} · client · Cadres de l'interface (demande de l'utilisateur : « cadres ornés dessinés pour le jeu ») : 15 SVG dessinés pour le jeu dans \`godot/art/ui/frames/\` (fenêtre, plaque de titre, carte et ses états, emplacement et emplacement actif, boutons bois et or, onglets, plaque de prix, info-bulle, auvent), bois sombre et dorures, inspirés de \`docs/ui_atlas.png\` sans copie ni décalque, couleurs de \`LhtPalette\` seulement (\`WOOD_DARK\`, \`WOOD\`, \`WOOD_LIGHT\`, \`GILT_SHADOW\`, \`GILT_LIGHT\`, \`OUTLINE\` ajoutées). Ils sont embarqués dans \`lht_theme.tres\` en \`DPITexture\` dans des \`StyleBoxTexture\` : l'essai a validé 4.7.2 en headless, dans le thème enregistré et redessiné net à 100, 125 et 200 % ; le repli prévu (textures cuites en \`.res\`) n'est pas utilisé. \`check_ui_frames\` et \`test_theme_frames\` gardent la table \`FRAMES\` et les fichiers alignés.
- D-417 · ${D} · client · Application du thème : les marges de contenu restent exactement celles de l'apparence à plat (aucune mise en page ne bouge), les ornements débordent par les marges d'extension seulement ; survol, désactivé et appui du bouton doré sont des teintes du dessin normal. \`PanelContainer\` et \`Panel\` sans variation prennent le cadre de fenêtre, et non la carte comme le prévoyait la conception, car les panneaux sans variation du jeu sont des fenêtres (menu, Paramètres, bilans, dialogues) ; une carte demande \`CardPanel\`. \`OptionButton\`, \`PopupMenu\` et barres de défilement sont habillés de bois ; contours de focus à plat. Nouvelle variation \`SlotPanelActive\` ; l'auvent est une icône du thème (\`FRAME_ICONS\`). 14 icônes ajoutées (améliorer, cadenas, coche, sablier, flèche, enclume, marteau, transfert, codex, crâne, épée, couronne, appât, plus).
- D-418 · ${D} · client · Bouton « Améliorer » / « Construire » uniforme (demande de l'utilisateur) : en haut de chaque panneau de bâtiment (\`SidePanel.header_actions()\`), il ouvre \`upgrade_dialog.tscn\` (niveau actuel → visé, coûts, ce que le niveau débloque, refus, Annuler / Confirmer) ; seule la confirmation envoie la requête ; la section du bas disparaît ; les cartes du QG ouvrent la même fenêtre. Le bouton n'est désactivé que pendant une requête ou avant le chargement du village : un refus (points de QG, or) ouvre quand même la fenêtre, qui dit pourquoi avec « Confirmer » désactivé. La fenêtre est un enfant \`top_level\` du panneau (fond assombri) ; Échap et le clic droit la ferment avant le panneau ; elle se ferme après un succès, quand le panneau se cache ou quand le niveau change ailleurs.
- D-419 · ${D} · client · Niveau maximal (écart à la conception, qui désactivait le bouton) : le bouton du panneau lit « Niveau maximal », style bois, et reste cliquable — la fenêtre montre « Niveau maximal atteint. » et ce que le bâtiment a débloqué, avec « Fermer » seul — pour que le bouton soit présent partout de la même façon ; sur les cartes du QG, résumé compact, il est masqué à ce niveau.
- D-420 · ${D} · client · QG, Hutte et Temple en grilles de cartes (\`Layout.GRID\` + \`CardGrid\`) : QG en \`building_card.tscn\`, Hutte en cartes d'offre de \`HuntsPanel\`, Temple en \`codex_tile.tscn\` (icônes quête, chasse, titan mondial) ; colonnes comptées sur la carte la plus large, plancher 260 px (QG), 300 (Hutte, Temple), 360 (titans mondiaux du Temple), si bien qu'une longue traduction ne fait jamais défiler le corps de côté (QG sur 2 colonnes en 1920 × 1080 à 100 %). Guilde et Tour du mage restent \`SIDE\`. Le côté du panneau et le cadrage de la caméra se calculent sur la zone de sa disposition. \`VillageIcons\` (\`core/village\`) prend l'icône du thème quand elle existe, sinon une icône existante ou un glyphe (« → »).
- D-421 · ${D} · client · La légende du QG « Chaque titan de la quête principale vaincu rapporte un point de QG… » ne s'affiche que si le serveur n'envoie pas de description (qui le dit déjà).
