const fs=require("fs");const p="C:/travaille/godot/towermoulineux2/docs/v1/";
const M=process.argv[2], TESTS=process.argv[3], LINT=process.argv[4], ART=process.argv[5];
function rep(f,a,b){let s=fs.readFileSync(p+f,"utf8");if(!s.includes(a))throw new Error(f+": "+a.slice(0,60));s=s.replace(a,b);fs.writeFileSync(p+f,s);}
const dec=`### Retours de réunion du 2026-10-16 — vague 6.3 (intégration)

- D-426 · 2026-10-16 · client · Les dernières boîtes à plat bleu nuit passent au thème : bandeau du titan et bandeau compact du HUD de combat en \`CardPanel\`, annonces de phase en plaques \`TooltipPanel\`, carte d'annonce du monde en \`CardPanel\` et nouvelle variation \`CardPanelSelected\` (cadre \`card_selected\`, sans nouveau SVG) pour le dernier coup du joueur. Gardés exprès : l'alerte rouge pulsante du monde (alarme) et le bandeau du parchemin (couleurs du parchemin).
- D-427 · 2026-10-16 · client · Étal du Marchand : l'auvent est l'icône \`awning\` du thème répétée (\`STRETCH_TILE\`), posée en premier dans le corps sous le titre, au-dessus de l'étal ; les cartes de coffre se partagent la largeur de l'étal (340 à 540 px chacune), icône de coffre 96 px, cotes sur deux lignes (précise D-422).
- D-428 · 2026-10-16 · client · Alegreya dessine des chiffres alignés (\`lnum\`) : ses chiffres elzéviriens ressemblaient à des indices (« 125 % »). En japonais, « フェーズ4 » et « レベル1 » restent un peu petits : ces libellés passent par une police de repli, laissés tels quels.
- D-429 · 2026-10-16 · client · La carte de la tour sélectionnée dans la vallée garde son cadre entier à toute hauteur : le cadre (\`TowerCardFrame\`, \`CardPanel\`) entoure la zone de défilement et la carte défilée ne dessine plus le sien ; la barre de défilement reste dans le cadre.
- D-430 · 2026-10-16 · client · Nombres de dégâts flottants en couloirs : chaque nombre prend le premier des 5 couloirs libres à côté du point d'impact, mesurés en em d'écran à la profondeur du coup ; un couloir reste pris 0,43 s et les nombres montent à vitesse constante (2,8 em) : plus de chevauchement (un 5 et un 3 lus « 53 »), même écart à tout zoom, déterministe.
- D-431 · 2026-10-16 · client · Pendant un combat, un panneau \`WIDE\` (Marchand, Atelier) commence sous le bandeau compact du titan : le module combat réserve la bande du haut (\`reserve_top(holder, bottom)\` de la vallée, \`CombatHud.banner_rect()\`, plus \`ScreenRoom.GAP\`) et \`SidePanel.top_clearance\` descend la zone du panneau, ornements du cadre compris ; elle revient à la normale quand le bandeau disparaît.
- D-432 · 2026-10-16 · client · Lignes « débloque » de la fenêtre d'amélioration : le mot du genre (« Chasse », « Coffre ») n'est pas répété quand le nom du catalogue le contient déjà (« Chasse des crêtes ») ; sinon il mène la ligne (« Chasse : {hunt} »), et dans la liste « Déjà débloqué » il suit le nom entre parenthèses (« {hunt} (chasse) ») : jamais deux deux-points de suite.
- D-433 · 2026-10-16 · client · Captures : prises 1440 × 1080 à 125 % des panneaux larges (Marchand, ouverture, Atelier en fusion, transfert, résultat) et \`menu_settings_ui125_1280x720\` (nommée comme les autres prises \`*_ui125_*\`, le suffixe \`_LxH\` reste en dernier) ; nouvelle trace du moteur \`hunt_kill\` (chasse tuée au tick 394, générée par \`td_sim_cli\`, les 6 autres traces identiques à l'octet) pour la capture de mort LHT1, dont l'étiquette est celle d'une chasse. Ses données (400 PV, 2 phases) viennent du catalogue de test du combat, pas de celui de la Hutte : sans effet sur le jeu.
- D-434 · 2026-10-16 · client · Fuites à la sortie des tests : les références statiques de la vague 6 sont rendues (planches LHT1 d'\`ArtTitanSpriteSkins\`, textures des cadres de \`LhtThemeBuilder\` après la construction, établi de forge libéré avec son panneau, cache d'\`ArtIcons\` vidé avant de quitter). Reste ce qui précède la vague 6 : 4 RID \`DummyMesh\` (caches de maillages d'\`ArtTitanView\` et \`ArtTowerView\`) et environ 140 instances de classes statiques GDScript, présentes même sans test.
- D-435 · 2026-10-16 · client · La croix de fermeture des panneaux larges reste (D-407) alors que les autres panneaux ont un bouton « Fermer » encadré ; relevé par la revue visuelle, à trancher avec l'utilisateur.

`;
rep("DECISIONS.md","\n## Règles de jeu V1","\n"+dec+"## Règles de jeu V1");
rep("PLAN.md","| 6.3 | `v1-w6-integration` |","| 6.3 ✅ | `v1-w6-integration` |");
rep("PLAN.md","**6.2** fusionnée le 2026-10-16 (`b093ed3`), D-416 à D-425.","**6.2** fusionnée le 2026-10-16 (`b093ed3`), D-416 à D-425. **6.3** fusionnée le 2026-10-16 (`"+M+"`), D-426 à D-435.");
rep("CONTRACTS.md","appliqués aux bus `Music` et `SFX` (D-414) ;","appliqués aux bus `Music` et `SFX` (D-414) ; `hunt_titan_style` facultatif, `3d` (défaut) ou `lht1` : apparence des titans de chasse en combat (D-424) ;");
rep("CONTRACTS.md","`hide_side_panel(panel)`, `side_panel()`","`hide_side_panel(panel)`, `side_panel()`, `reserve_top(holder, bottom)` (bande du haut réservée par un module, ainsi le bandeau du combat : les panneaux `WIDE` commencent dessous, D-431)");
const st=`
## Retours de réunion du 2026-10-16 — vague 6.3, intégration (fusionnée dans \`v1\`)

Une branche \`v1-w6-integration\` partie de \`v1\` (\`bd97e4c\`), relue sous trois angles (rendu, traductions, régressions) puis corrigée, fusionnée le 2026-10-16 (\`${M}\`). D-426 à D-435.

| Sujet | État | Preuve |
|---|---|---|
| Restes de la 6.2 (bandeau du combat, auvent, prises à 125 %, mort LHT1) | ✅ | \`test_theme_frames\` (\`CardPanelSelected\`), \`test_village_wide_panels\` (auvent du thème en tête de l'étal, largeur des coffres, bandeau au-dessus d'un panneau large à 100 et 125 %), \`test_engine_traces\` (\`hunt_kill\`) (D-426, D-427, D-431, D-433). |
| Bascule de langue en direct | ✅ | \`test_i18n_live_switch.test_the_village_windows_bench_and_grids\` (fr → de → en : fenêtre d'amélioration, Marchand, « Vous avez obtenu », établi en fusion et transfert, grilles QG, Hutte, Temple, barre du Village) ; sections Son et Combat des Paramètres. |
| Captures fr, ru, de, ja | ✅ | 243 PNG fenêtrés (6 listes en fr ; menu, village, combat, monde et revue de la vallée en ru, de, ja à 1280 × 720 avec les prises à 125 %), chaque vue relue au moins une fois par langue ; défauts corrigés : chiffres d'Alegreya (D-428), cadre de la carte de tour coupé (D-429), nombres de dégâts superposés (D-430, \`test_combat_damage_numbers\`), « Chasse : Chasse des … » (D-432). |
| E2E contre le vrai serveur | ✅ | 127.0.0.1:18094, schémas jetables de \`lht2_test\` : \`dev.ps1 journey\` 27/27, \`e2e.ps1 double-spend\` et \`layout-during-combat\` (17 vérifications, 0 échec), \`real_server_village\` 64/0. |
| Fuites à la sortie des tests | ✅ partiel | sources de la vague 6 levées (D-434) ; restent 4 RID et ~140 instances statiques antérieures à la vague 6. |

| Vérification (\`v1\` \`${M}\`, orchestrateur) | Résultat |
|---|---|
| \`run_tests.gd\` | ${TESTS} |
| \`check_scripts.gd\` (lint, \`-d\`) | ${LINT} |
| \`art_checks.gd\` | ${ART} |
| Go | inchangé depuis 6.1 (aucun fichier \`serveur/\` touché) |

Points ouverts de la vague 6 : musiques et sons non écoutés par l'orchestrateur ; licences des musiques, sons et sprites de LHT1 non vérifiées (README) ; or du titan mondial par heure divisé par 3 (D-405) ; croix de fermeture des panneaux larges (D-435) ; données du serveur (noms, descriptions) en français dans toutes les langues (D-389) ; fond assombri de la fenêtre d'amélioration qui ne couvre pas le HUD (sans effet) ; \`dev.ps1 journey\` et \`e2e.ps1\` créent leurs schémas par \`docker exec … psql\`, refusé par le mode automatique : à faire passer par \`LHT_TEST_DATABASE_URL\`.
`;
rep("STATUS.md","étiquette brute).\n","étiquette brute).\n"+st);
console.log("ok");

