const fs = require("fs"); const p = "C:/travaille/godot/towermoulineux2/docs/v1/";
function rep(f, a, b, all) { let s = fs.readFileSync(p + f, "utf8"); if (!s.includes(a)) throw new Error(f + ": " + a.slice(0, 70)); s = all ? s.split(a).join(b) : s.replace(a, b); fs.writeFileSync(p + f, s); }

// DECISIONS
const dec = `
### Vague 7.1 : fiche de tour, fontaine de dégâts, filtres de l'Atelier, moteur règles v2

- D-444 · 2026-10-19 · client · Fiche de tour en trois blocs (Caractéristiques, Propriétés, Voisinage, séparés par des filets dorés \`CardRule\`) ; la ligne « Élément » disparaît : la ligne des dégâts montre une valeur et une icône d'élément par part, réparties exactement comme le moteur (chaque part convertie arrondie à l'inférieur, le reste à l'élément de l'archétype, la plus grosse d'abord), les parts sous la valeur (« Feu 50 % · Neutre 50 % ») ; une part seule affiche aussi le nom de l'élément ; la brûlure montre son élément (icône et nom).
- D-445 · 2026-10-19 · client · Qualité d'une propriété tirée : la rareté dont la plage du catalogue (\`modifiers[].ranges\`) contient la valeur ; si plusieurs la contiennent, la rareté de la tour si elle en fait partie, sinon la plus haute ; au-dessus de toutes les plages, la plus haute atteinte ; en dessous, la plus basse. Un bonus de voisinage prend sa rareté explicite ; un bonus reçu, la rareté de voisinage de la tour source. À remplacer par la rareté du tirage si la vague 7.2 la stocke.
- D-446 · 2026-10-19 · client · Capsule \`BonusChip\` commune aux propriétés, au bonus donné et aux bonus reçus : icône de la catégorie, nom, valeur, gemme et liseré de la couleur de qualité, infobulle « Qualité » et « transférable à l'Atelier » ; une conversion affiche « 100 % → » et l'icône de l'élément. Icônes de bonus : le glyphe de la stat avec un médaillon doré (« + » pour une force ou un fixe, horloge pour une durée, flèches pour une conversion), plus une icône générique pour une catégorie future. La valeur passe sous le nom dès que le mot le plus long du nom ou de la source ne tient pas à côté : aucun mot coupé (de, ru, 125 %).
