rep("PLAN.md", "| Godot (fixtures combat) | `python godot/tests/fixtures/combat/make_fixtures.py` (après le build Release du moteur) | 6 scénarios régénérés à l'identique (`git status` propre) |",
  "| Godot (fixtures combat) | `(cd serveur && go run ./cmd/makefixtures)` (après le build Release du moteur ; D-457) | scénarios et trace d'exemple régénérés à l'identique (`git status` propre) ; `TestCombatFixturesAreUpToDate` |");
rep("PLAN.md", "`python godot/art/tests/layouts/make_layouts.py` (moteur Release construit)", "`(cd serveur && go run ./cmd/makefixtures -only layouts)` (moteur Release construit)");

// CONTRACTS §2
const C = "CONTRACTS.md";
rep(C, "`schema_version` = **2**, `ruleset_version` = **`tdsim.rules.v1`**. L'ancien champ `contract_version` est supprimé.",
  "`schema_version` = **3**, `ruleset_version` = **`tdsim.rules.v2`**, `engine_version` 2.x (le serveur exige la même version majeure, D-449). Le moteur refuse le schéma 2 et `tdsim.rules.v1`. L'ancien champ `contract_version` est supprimé.");
rep(C, "JSON strict : un document lisible mais mal formé", "Nouveaux codes v2 : `InvalidAbsorbValue`, `InvalidStraightAccel`, `InvalidDotStacks`.\n\nJSON strict : un document lisible mais mal formé");
rep(C, '  "schema_version": 2,\n  "ruleset_version": "tdsim.rules.v1",\n  "seed"', '  "schema_version": 3,\n  "ruleset_version": "tdsim.rules.v2",\n  "seed"');
rep(C, '{ "speed_units_per_tick": 650, "resistances": [ { "element_id": 1, "resistance_bp": 4000 } ] }',
  '{ "speed_units_per_tick": 650, "resistances": [ { "element_id": 1, "resistance_bp": 4000, "absorb_bp": 2000 } ],\n        "straight_accel": { "after_steps": 3, "add_bp_per_step": 1000, "max_bp": 5000 } }');
rep(C, '{ "effect_id": 2, "kind": "Dot", "element_id": 0, "damage_per_period": 3, "period_ticks": 20, "duration_ticks": 60 }',
  '{ "effect_id": 2, "kind": "Dot", "element_id": 1, "damage_per_period": 3, "period_ticks": 20, "duration_ticks": 60, "max_stacks": 3 }');
rep(C, '      "first_fire_tick": 0,', '      "first_fire_tick": 0,\n      "attacks": true,');
rep(C, "| résistances | `element_id` ∈ [0, 15] unique par phase ; `resistance_bp` ∈ [-10000, 9500] |",
  "| résistances | `element_id` ∈ [0, 15] unique par phase ; `resistance_bp` ∈ [-10000, 10000] (10000 = immunité) ; `absorb_bp` facultatif ∈ [0, 10000], 0 par défaut (`InvalidAbsorbValue`) |\n| `straight_accel` (phase, facultatif) | `after_steps` ∈ [1, 4096], `add_bp_per_step` ∈ [1, 10000], `max_bp` ∈ [1, 30000] (`InvalidStraightAccel`) ; absent = pas d'accélération |\n| `attacks` (tour, facultatif) | booléen, vrai par défaut ; faux : la tour ne tire jamais (soutien, D-454) ; accepté aussi par `stats` |");
rep(C, "`period_ticks`, `duration_ticks` ∈ [1, 72000] |", "`period_ticks`, `duration_ticks` ∈ [1, 72000] ; `max_stacks` (Dot seulement, facultatif) ∈ [1, 8], 1 par défaut (`InvalidDotStacks` ; sur un Slow : `UnknownField`) |");
rep(C, "La phase ne redescend jamais.", "En combat, la phase suit les PV dans les deux sens (D-450).");
rep(C, "| `DotForceAddBp` | chaque effet Dot : `damage_per_period` × (10000 + Σbp) / 10000, arrondi bas, ≥ 1 |",
  "| `DotForceAddBp` | chaque effet Dot, en centièmes : max(100, ⌊`damage_per_period` × (10000 + Σbp) / 100⌋ + 100 × Σ`DamageAddFlat`) : les dégâts fixes s'ajoutent à chaque tic, sans être multipliés par la force (D-452) |");
rep(C, "- Dégâts par tir : pour chaque part élémentaire, `⌊part × (10000 − résistance) / 10000⌋` avec la résistance de la phase courante, puis somme.",
  "- Dégâts par tir : pour chaque part élémentaire R, `absorbed = ⌊R × absorb / 10000⌋` (soigne, §2.4), puis `⌊(R − absorbed) × (10000 − résistance) / 10000⌋` avec la résistance de la phase courante, puis somme (D-451).");
rep(C, "sinon elle ne tire jamais et n'émet aucun événement (tour de soutien pure ; l'erreur V0 `EmptyTower` est supprimée).",
  "sinon elle ne tire jamais et n'émet aucun événement (tour de soutien pure ; l'erreur V0 `EmptyTower` est supprimée). Une tour `attacks: false` ne tire jamais.");
rep(C, "### 2.3 Pathfinding (`tdsim.rules.v1`)", "### 2.3 Pathfinding (inchangé depuis `tdsim.rules.v1`)");
rep(C, "| `InvalidInput` / `InvalidLayout` / `NoPath` | aucune simulation ; `errors[]` renseigné |\n",
  "| `InvalidInput` / `InvalidLayout` / `NoPath` | aucune simulation ; `errors[]` renseigné |\n\nAjouts v2 :\n- **Soins** : un coup retire ses dégâts, puis rend ses parts absorbées par élément croissant, jamais au-delà de `max_hp` ni à 0 PV (D-451).\n- **Phase** : recalculée après chaque coup et ses soins, dans les deux sens ; elle s'applique au coup et au déplacement suivants, figée à la mort (D-450).\n- **Brûlures** : en centièmes, reste gardé par brûlure (dégâts et soins séparément) ; un nouveau cumul prend le plus petit emplacement libre, au plafond celui qui finit le premier est rafraîchi (D-452).\n- **Ligne droite** : vitesse = max(1, ⌊base × (10000 + bonus) × (10000 − ralentissement) / 10^8⌋), bonus = borne((série − `after_steps`) × `add_bp_per_step`, 0, `max_bp`), série comptée en pas de même direction (D-453).\n");
rep(C, '  "schema_version": 2,\n  "ruleset_version": "tdsim.rules.v1",\n  "engine_version": "1.0.0",', '  "schema_version": 3,\n  "ruleset_version": "tdsim.rules.v2",\n  "engine_version": "2.0.0",');
rep(C, '"towers": [ { "id": 1, "shots": 40, "direct_damage": 200, "dot_damage": 90 } ]', '"towers": [ { "id": 1, "shots": 40, "direct_damage": 200, "dot_damage": 90, "healed": 0 } ]');
rep(C, "- `direct_damage` / `dot_damage` = PV réellement retirés (sans overkill, dans l'ordre exact des événements) : leur somme sur toutes les tours vaut `damage_dealt`. `phase_enter_ticks` : une entrée par phase atteinte, phase de départ comprise.",
  "- `direct_damage` / `dot_damage` = PV réellement retirés (sans overkill, dans l'ordre exact des événements), `healed` = PV rendus par absorption : Σ(`direct_damage` + `dot_damage` − `healed`) = `initial_hp` − `remaining_hp` ; `damage_dealt` = max(0, `initial_hp` − `remaining_hp`). `phase_enter_ticks` : première entrée de chaque phase, de la phase de départ à la plus haute atteinte ; `final_phase` peut être plus basse (D-450).");
rep(C, '{"kind":"Header","trace_format":"lht.trace.live.v1","schema_version":2,"ruleset_version":"tdsim.rules.v1",', '{"kind":"Header","trace_format":"lht.trace.live.v1","schema_version":3,"ruleset_version":"tdsim.rules.v2",');
rep(C, '{"tick":14,"kind":"StatusStart","tower":3,"effect":1,"status":"slow","until":74}', '{"tick":14,"kind":"StatusStart","tower":3,"effect":1,"stack":0,"status":"slow","until":74}');
rep(C, '{"tick":74,"kind":"StatusEnd","tower":3,"effect":1,"status":"slow"}', '{"tick":40,"kind":"Heal","tower":4,"effect":2,"element":1,"amount":1,"hp":1461}\n{"tick":74,"kind":"StatusEnd","tower":3,"effect":1,"stack":0,"status":"slow"}');
rep(C, "| `Move` | `progress`, `speed` | tick 0, puis à chaque changement de vitesse effective (slow, phase), et `speed: 0` à la fin |", "| `Move` | `progress`, `speed` | tick 0, puis à chaque changement de vitesse effective (slow, phase, ligne droite), et `speed: 0` à la fin |");
rep(C, "| `StatusStart` | `tower`, `effect`, `status` (`slow`/`dot`), `until` (tick exclusif) | effet qui devient actif (pas sur rafraîchissement) |\n| `StatusEnd` | `tower`, `effect`, `status` | effet qui expire |\n| `Phase` | `phase` | changement de phase ;",
  "| `Heal` | `tower`, `effect` (0 pour un tir, l'id de la brûlure pour un tic), `element`, `amount` (> 0, PV réellement rendus), `hp` | part absorbée d'un coup (v2) |\n| `StatusStart` | `tower`, `effect`, `stack` (cumul, 0 pour un Slow), `status` (`slow`/`dot`), `until` (tick exclusif) | effet qui devient actif (pas sur rafraîchissement) ; un statut = (tour, effet, cumul) |\n| `StatusEnd` | `tower`, `effect`, `stack`, `status` | effet qui expire |\n| `Phase` | `phase` | changement de phase, à la hausse comme à la baisse (v2) ;");
rep(C, "`Attack`, `StatusStart` et `Phase` à tick + 1 (résolus après le déplacement) ;", "`Attack`, `StatusStart` à tick + 1 (résolus après le déplacement) ; `Heal` à tick + 1 après un tir (`effect` 0), à son tick après un tic de brûlure ; `Phase` avec le coup ou le soin qu'il suit ;");
rep(C, "- Ordre dans un tick : `StatusEnd`, `Dot`, `Move`, `Attack`, `StatusStart`, `Phase`, puis `Move` (vitesse 0) et `End`.",
  "- Ordre dans un tick (v2) : `StatusEnd` ; pour chaque brûlure due, `Dot`, ses `Heal`, son `Phase` ; `Move` ; pour chaque tir, `Attack`, ses `Heal`, son `Phase` ; `StatusStart` ; puis `Move` (vitesse 0) et `End`. `Phase` n'est plus émis en fin de tick.");
rep(C, '  "schema_version": 2, "ruleset_version": "tdsim.rules.v1",\n  "valid": true,', '  "schema_version": 3, "ruleset_version": "tdsim.rules.v2",\n  "valid": true,');
rep(C, "- `stats` : entrée `{ \"schema_version\": 2, \"ruleset_version\": \"tdsim.rules.v1\", \"towers\": [ ... ] }`", "- Chaque brûlure de `analyze` et `stats` porte, dans cet ordre : `effect_id`, `kind`, `element_id`, `damage_per_period` (centièmes / 100, arrondi bas, pour l'affichage), `damage_per_period_x100`, `period_ticks`, `max_stacks`, `duration_ticks` (D-456).\n- `stats` : entrée `{ \"schema_version\": 3, \"ruleset_version\": \"tdsim.rules.v2\", \"towers\": [ ... ] }`");
rep(C, "## 2. Simulateur TD-SIM v1 (`lhtcpp/`)", "## 2. Simulateur TD-SIM, règles v2 (`lhtcpp/`)");
// §3
rep(C, "| `archetypes.json` | `{ archetypes }` | `archer`, `catapult`, `mage`, `fire` (table A2) |", "| `archetypes.json` | `{ archetypes }` | `archer`, `catapult`, `mage`, `fire` (table A2) ; facultatifs : `attacks` (false), `innate` [{ `modifier`, `value`, `element?`, `cells?` }], `max_stacks` sur une brûlure (D-452, D-454) ; servis par le catalogue, omis quand absents |");
rep(C, "| `titans.json` | `{ titans }` | titans MSQ, chasse et mondiaux |", "| `titans.json` | `{ titans }` | titans MSQ, chasse et mondiaux ; par phase, résistances jusqu'à 10000, `absorb` { élément: bp } et `straight_accel` { `after_steps`, `add_bp_per_step`, `max_bp` } facultatifs (D-451, D-453) |");
console.log("ok");

