package inventory

import (
	crand "crypto/rand"
	"fmt"
	"math/rand/v2"

	"lht2/serveur/internal/catalog"
)

// RNG draws uniform integers in [0, n). *rand.Rand of math/rand/v2 implements it.
type RNG interface {
	IntN(n int) int
}

// NewRNG returns a generator seeded by the operating system. It is not safe
// for concurrent use: create one per operation.
func NewRNG() RNG {
	var seed [32]byte
	if _, err := crand.Read(seed[:]); err != nil {
		panic(fmt.Errorf("seed the tower generator: %w", err)) // the OS entropy source never fails in practice
	}
	return rand.New(rand.NewChaCha8(seed))
}

// RandomArchetype draws an archetype uniformly.
func RandomArchetype(c *catalog.Catalog, rng RNG) string {
	archetypes := c.Archetypes()
	return archetypes[rng.IntN(len(archetypes))].ID
}

// Roll draws the modifiers of a new tower (D-104 to D-106), deterministically
// for a given RNG:
//   - PRIM: prim_count distinct categories among those applicable to the
//     archetype (slow_* need a Slow effect, dot_* a Dot effect), each at a
//     uniform value of the tower rarity's range; a conversion also draws its
//     target element among element_choices. Rolls are listed in catalog order;
//   - neighbor: one neighbor-eligible category, a bonus rarity drawn in the
