// 12:00) until the balance wave retunes the pace (D-438): the pace is
// criterion C1 of TestProgressionReport, this test guards against a dead end
// and a further slowdown. Engine required, about half a minute.
func TestNoDeadEnd(t *testing.T) {
	c, err := catalog.Load()
	if err != nil {
		t.Fatal(err)
	}
	engine := newEngine(t, c)
	limits := balance.V1Thresholds
	limits.Horizon += 4 * balance.Hour
	var scenarios []balance.Scenario
	for index, order := range powerLast(c) {
		profile := balance.ReferenceProfile.WithVillage(order)
		for seed := range uint64(2) {
			scenarios = append(scenarios, balance.Scenario{Name: profile.Name + " ×1", Players: []balance.Profile{profile},
				Seed: seed + 1, Horizon: limits.Horizon})
		}
		if index == 0 {
			scenarios = append(scenarios, balance.Scenario{Name: profile.Name + " ×5", Players: slices.Repeat([]balance.Profile{profile}, 5),
				Seed: 1, Horizon: limits.Horizon})
		}
	}
	if len(scenarios) == 0 {
		t.Fatal("no village order")
	}
	outcomes, err := balance.RunAll(context.Background(), c, engine, scenarios, workers())
	if err != nil {
		t.Fatal(err)
	}
	for _, outcome := range outcomes {
		for _, player := range outcome.Players {
			attempts := 0
			for _, count := range player.Attempts {
				attempts += count
			}
			if quest := len(player.Fights[balance.ActivityQuest]); quest != attempts || len(player.Fights[balance.ActivityWorldFight]) != len(player.Visits) {
				t.Errorf("%s: %d quest fights recorded for %d attempts, %d world fights for %d visits", outcome.Scenario.Name,
					quest, attempts, len(player.Fights[balance.ActivityWorldFight]), len(player.Visits))
			}
		}
	}
	for _, verdict := range balance.QuestVerdicts("worst village orders", outcomes, limits, false) {
		if !verdict.Pass {
			t.Error(verdict)
		} else {
			t.Log(verdict)
		}
	}
}

