package balance_test

import (
	"context"
	"slices"
	"testing"

	"lht2/serveur/internal/balance"
	"lht2/serveur/internal/catalog"
)

// TestDataMeetsTheBalanceCriteria checks the criteria that only depend on
// the data (C1: gold can always be earned and turned into towers without a
// QG point; C2: every QG point, catalyst and surplus tower has a use; C3:
// the reference village order pays each unlock the quest calibration counts
// on with the QG points of the tiers before).
func TestDataMeetsTheBalanceCriteria(t *testing.T) {
	c, err := catalog.Load()
	if err != nil {
		t.Fatal(err)
	}
	for _, verdict := range balance.DataVerdicts(c) {
		if !verdict.Pass {
			t.Error(verdict)
		}
	}
}

// powerLast returns the village orders that buy last the levels turning
// gold into towers (chests, fusion): the worst orders for a blocked player.
func powerLast(c *catalog.Catalog) [][]balance.Step {
	power := func(step balance.Step) bool {
		building, _ := c.Building(step.Building)
		level, _ := building.Level(step.Level)
		for _, id := range level.Unlocks {
			if _, chest := c.Chest(id); chest || id == catalog.FeatureFusion {
				return true
			}
		}
		return false
	}
	var worst [][]balance.Step
	for _, order := range balance.VillageOrders(c) {
		tail := len(order)
		for tail > 0 && power(order[tail-1]) {
			tail--
		}
		if !slices.ContainsFunc(order[:tail], power) {
			worst = append(worst, order)
		}
	}
	return worst
}

// TestNoDeadEnd plays model players who buy their village in the worst
// orders, alone and five together (the last hits of the world titan are
// then shared): each completes the quest within
// balance.V1Thresholds.Horizon plus 12 hours. Since towers roll fewer bonuses
// (D-440) and grid sizes are bought (D-443), the slowest of these orders ends
// far past the V1 horizon (22:13 for 12:00, with a 14:42 stall on tier 6 when
// the Merchant level 2 and the Workshop come last) until the balance wave
// retunes the pace (D-438): the pace is criterion C1 of TestProgressionReport,
// this test guards against a dead end. Engine required, about half a minute.
func TestNoDeadEnd(t *testing.T) {
	c, err := catalog.Load()
	if err != nil {
		t.Fatal(err)
	}
	engine := newEngine(t, c)
	limits := balance.V1Thresholds
	limits.Horizon += 12 * balance.Hour
	var scenarios []balance.Scenario
	for index, order := range powerLast(c) {
		profile := balance.ReferenceProfile.WithVillage(order)
		for seed := range uint64(2) {
			scenarios = append(scenarios, balance.Scenario{Name: profile.Name + " ×1", Players: []balance.Profile{profile},
				Seed: seed + 1, Horizon: limits.Horizon})
		}
		if index == 0 {
			scenarios = append(scenarios, balance.Scenario{Name: profile.Name + " ×5", Players: slices.Repeat([]balance.Profile{profile}, 5),
				Seed: 1, Horizon: limits.Horizon})
		}
	}
	if len(scenarios) == 0 {
		t.Fatal("no village order")
	}
	outcomes, err := balance.RunAll(context.Background(), c, engine, scenarios, workers())
	if err != nil {
		t.Fatal(err)
	}
	for _, outcome := range outcomes {
		for _, player := range outcome.Players {
			attempts := 0
			for _, count := range player.Attempts {
				attempts += count
			}
			if quest := len(player.Fights[balance.ActivityQuest]); quest != attempts || len(player.Fights[balance.ActivityWorldFight]) != len(player.Visits) {
				t.Errorf("%s: %d quest fights recorded for %d attempts, %d world fights for %d visits", outcome.Scenario.Name,
					quest, attempts, len(player.Fights[balance.ActivityWorldFight]), len(player.Visits))
			}
		}
	}
	for _, verdict := range balance.QuestVerdicts("worst village orders", outcomes, limits, false) {
		if !verdict.Pass {
			t.Error(verdict)
		} else {
			t.Log(verdict)
		}
	}
}

