input.command:
node -e '
const r=f=>JSON.parse(require("fs").readFileSync(f,"utf8"));
const h=r("hunts.json");for(const x of h.hunts)console.log(x.id,x.bait_cost_gold,JSON.stringify(x.kill_rewards),x.cooldown_seconds);
const t=r("titans.json");for(const x of t.titans){console.log(x.id,x.max_hp||("scale "+x.hp_scale_bp),JSON.stringify(x.phases||x.behavior||"").slice(0,260));}
const b=r("buildings.json");for(const x of b.buildings)for(const l of x.levels)console.log(x.id,l.level,l.cost_qg_points??l.cost_qg,l.cost_gold);' 2>&1 | head -60; ls; grep -o '"tier":[0-9]*\|"gold":[0-9]*' msq.json | paste -sd' ' | cut -c1-600

