cd "C:/Users/akitl/AppData/Local/Temp/claude/C--travaille-godot-towermoulineux2/7020066a-783a-415a-a50d-d8623080aee1/scratchpad/w7" && cat > gen74.js <<'EOF'
const fs=require('fs');
const src=fs.readFileSync('wave73.js','utf8');
let head=src.slice(src.indexOf('const SP ='), src.indexOf('const BRANCHES'));
head=head.replace("(waves 6, 7.0, 7.1 and 7.2 merged: combat rules v2 engine 2.0.0; tower card in three blocks; damage fountain; bonus cap per rarity, Merchant tables, unique towers divine/aura/titan_relic; lottery world titan with HP by progression, random visits and visit_risk; Architect building selling grid sizes, server side only). Read docs/v1/STATUS.md (sections of wave 7) and docs/v1/DECISIONS.md D-436 to D-481 first",
 "(waves 6 and 7.0 to 7.3 merged: combat rules v2 engine 2.0.0; tower card in three blocks; damage fountain; bonus cap, Merchant tables, unique towers; lottery world titan with visit risk; Architect building and panel selling grid sizes; pace retuned to 8-12 h with a puzzle main quest; painted trail and arena border; giant world titan; HP bar mechanic icons and heals). Read docs/v1/STATUS.md (sections of wave 7) and docs/v1/DECISIONS.md D-436 to D-509 first");
head=head.replace("- THREE BRANCHES RUN IN PARALLEL (balance, client-world-architect, path-arena), merged in that order. Keep edits to files another branch may touch small and additive.\n","- ONE BRANCH in this wave (v1-w7-integration): you may touch any path needed for a fix, but keep fixes small and say why.\n");
if(head.includes('THREE BRANCHES')) throw new Error('replace failed');
if(!head.includes('D-509')) throw new Error('replace ctx failed');
const meta=`export const meta = {
  name: 'wave7-4',
  description: 'Wave 7.4: integration of wave 7: captures in fr, ru, de and ja, live language switch, real-server E2E (journey with an Architect purchase, double spend, two-player world fight with the held death announcement), README updates, final review, then fixes',
  phases: [{ title: 'Implement' }, { title: 'Review' }, { title: 'Fix' }],
}
`;
const TASK=`Branch v1-w7-integration. Integration and acceptance of the whole wave 7 (feedback docs/retours_gd_2026-10-18.md in the main repo, plan C:\\\\Users\\\\akitl\\\\.claude\\\\plans\\\\nifty-rolling-crane.md, rows 7.4 and "Vérification").
1. CAPTURES (windowed, READ every PNG you cite): every screen wave 7 changed, at 1920x1080, 1280x720 and 1440x1080 at 125 % UI scale, in fr, ru, de and ja: tower card in three blocks (sheet and card, unique tower, tower without bonus, non-attacking aura), damage fountain and green heal numbers, HP bar with mechanic icons (each MSQ puzzle titan T2 to T10 from the real catalog: sprint, immunity, absorption, straight line), workshop with filters and a transfer into a free slot, Merchant, Architect panel (available, locked, max, during a fight) and the village bar, world banner, panel and button tooltip with the three risks, giant world titan in a fight, last-hit lot window, painted trail with turns and diagonals at 16x12 and 32x22, arena entry and exit, valley overview. Use the existing shot lists (tools/capture/shots/*.json: world_architect, arena, trail, loot, combat, world, ...) and add one list wave7.json covering what is missing. Look for: cut or overflowing text, untranslated msgids, overlaps, unreadable icons, wrong values. Fix every defect you find (i18n CSVs, layout), recapture and re-read. Known: Russian « Установлена » tag overlaps the rarity in the planning inventory: fix it.
2. LIVE LANGUAGE SWITCH: with the Architect panel, the world panel, the tower card, the HP bar tooltips and the lot window open, switch language at runtime (fr -> ru -> ja -> fr): every text re-renders, nothing stays in the old language; add or extend the automated test (tests already exist for live switch: extend them to the new wave 7 widgets).
3. E2E AGAINST A REAL SERVER on your port: (a) the journey (windowed) including a grid size purchase at the Architect after the tier that unlocks it, then a defense on the bigger grid; (b) double spend: two clients buying the same grid size / chest at the same time with the same and different keys, gold paid once; (c) two-player world fight: two headless clients present, a world titan with small HP set through the dev console, both fight, one deals the last hit: the killer gets the relic, the epic and 1000 gold, the other the gold by damage; the death announcement is held until each client's fight presentation ends (D-347) and shown to both. Reuse tests/e2e/* (journey, multi, double-spend, real_server_architect, world_two_clients). All green, server stopped by PID, schemas dropped.
4. DOCS outside docs/v1 (you may edit them): serveur/README.md still describes the old reference player (3 basic chests, 100 hunt gold, Arrange layout), the old world calibration test (TestWorldTitansOutliveManyVisits) and the old world values: update to D-482..D-494 (good player, TestWorldTitansLiveSeveralHours, player_hp 67 000..370 000, completed 400 000, max 4 000 000, hp_per_gold 150, report in about 6 min with -timeout 60m). godot/README.md: check it covers the trail, the arena border, the Architect and the unique looks.
5. FINAL REVIEW of wave 7 against the user's feedback, point by point (retours_gd_2026-10-18.md): for each point say done / partial / not done with evidence (test, capture path). Hunt integration bugs between the merged branches (for instance the Architect slot against the bigger arena, giant titan framing with the arena border, trail under the giant, risk text with the new values).
Run at the end: Go full suite with LHT_REQUIRE_ENGINE=1, Godot import x2, run_tests 0 failed (the two combat performance tests fail under machine load: rerun them alone if so), lint 0 WARNING, art_checks OK. Report the point-by-point review in the summary.`;
const body=`
const TASK = ${JSON.stringify(TASK)}
const PORT = 18083, RPORT = 18088
const impl = await agent(\`You implement wave 7.4 of LHT-2. In your own worktree: git switch -c v1-w7-integration && git reset --hard v1. Port LHT_TEST_HTTP_PORT=\${PORT}, real server on \${PORT + 10}.
\${TASK}
Atomic commits. Report: branch, worktree, commits, summary (with the point-by-point review), tests (exact counts), captures_read (list + one-line verdict each), decisions to record in DECISIONS.md (French, one line each), contract_changes, open issues.
\${ENV}\`, { label: 'impl:integration', phase: 'Implement', isolation: 'worktree', schema: IMPL_SCHEMA })
if (!impl) return { impl: null }
const review = await agent(\`ADVERSARIAL REVIEW of branch \${impl.branch} in worktree \${impl.worktree_path} (v1 plus commits: \${impl.commits.join('; ')}). Implementation summary: \${impl.summary}
Open issues reported: \${impl.open_issues.join(' | ')}
The task was:
\${TASK}
Check the point-by-point review against the user's feedback yourself (read docs/retours_gd_2026-10-18.md in the main repo): find points claimed done that are not, captures with defects the implementer missed (take your own windowed captures at 1920x1080, 1280x720 and 1440x1080 at 125 %, fr, ru, de, ja, READ them), E2E claims you cannot reproduce, bugs in the diff. Do NOT modify tracked files in that worktree (scratch under $TEMP/lht-review74/). Only real defects with evidence; empty list if none. Port LHT_TEST_HTTP_PORT=\${RPORT} (real server on \${RPORT + 10}).
\${ENV}\`, { label: 'review:integration', phase: 'Review', schema: REVIEW_SCHEMA })
const issues = review?.issues || []
let fix = null
if (issues.length) fix = await agent(\`You continue branch \${impl.branch} in its existing worktree \${impl.worktree_path} (cd there; no new worktree or branch). A reviewer reported:
\${JSON.stringify(issues, null, 1)}
For each: verify; fix if real (test for logic; recapture and READ for visuals) or reject with a precise reason; product decisions: reject with the reason. Then rerun the full verification (Go full suite with LHT_REQUIRE_ENGINE=1 if serveur/ is touched, Godot run_tests 0 failed, lint 0 WARNING, art_checks OK, the E2E you touched). Commit. Port LHT_TEST_HTTP_PORT=\${PORT}.
The original task:
\${TASK}
\${ENV}\`, { label: 'fix:integration', phase: 'Fix', schema: FIX_SCHEMA })
return { impl, issues, fix }
`;
fs.writeFileSync('wave74.js', meta+head+body);
EOF
node gen74.js && node -e '
const s=require("fs").readFileSync("wave74.js","utf8").replace(/^export const meta/,"const meta");
new Function("agent","return (async()=>{"+s+"})")' && echo SYNTAX_OK && grep -c $'\u2014' wave74.js

